Lemma mmap_fixed_free_sound2 : forall cs kd (eager visible : bool) flg csa csb E R FULL model TB,
  CSOK E cs R FULL model -> is_ecall_at SEGS cs = true ->
  reg_lit cs 17 = Some 222 ->
  reg_lit cs 12 = Some (if kind_none kd then 0 else 3) ->
  reg_lit cs 13 = Some flg -> 0 <= flg < two64 ->                                     (* [comment removed for export] *)
  AsanNodesMmLibK.fixed_free_core (mmap_flags_core (Z_to_bv 64 flg)) -> mmap_noreserve_b (Z_to_bv 64 flg) = kind_lazy kd ->
  reg_lit cs 14 = Some (two64 - 1) -> reg_lit cs 15 = Some 0 ->
  (kind_none kd || kind_lazy kd = negb eager)%bool -> is_tok_kind kd = false ->
  visible = eager ->
  mmap_fixed_free A LIMIT cs kd eager visible = Some (csa, csb) ->     (* [comment removed for export] *)
  (forall E' R' FULL' model', env_agree nx0 E E' /\ env_agree (nxt cs) E E' -> CSOK E' csb R' FULL' model' -> m_fs model' = m_fs model ->
      srealizes SEGS scfg (cfg R' (pc csb) FULL' model') TB) ->
